function reorder(
  productSku: string,
  minStock: number,
  reorderPoint: number,
  safetyStock: number,
  reorderQty: number,
  preferredSupplier: string,
  leadTimeDays: number,
): ReorderRule {
  return { productSku, minStock, reorderPoint, safetyStock, reorderQty, preferredSupplier, leadTimeDays };
}

