/* ------------------------------------------------------- history generator */

interface MoveSpec {
  at: string;
  type: Extract<LedgerType, 'OPENING' | 'RECEIPT' | 'DELIVERY' | 'TRANSFER' | 'ADJUSTMENT'>;
  ref: string;
  qty: number;
  /** Receipts and adjustments land here. */
  to?: string;
  /** Deliveries and transfers leave from here. */
  from?: string;
  /** Transfers only. */
  toMove?: string;
  user: string;
  note: string;
}

class HistoryBuilder {
  private balances = new Map<string, Map<string, number>>();
  readonly ledger: LedgerEntry[] = [];
  private n = 0;

  constructor(private products: Map<string, Product>) {}

  private leaves(sku: string): Map<string, number> {
    let m = this.balances.get(sku);
    if (!m) {
      m = new Map();
      this.balances.set(sku, m);
    }
    return m;
  }

  private apply(sku: string, location: string, delta: number): void {
    const m = this.leaves(sku);
    const next = Math.round(((m.get(location) ?? 0) + delta) * 1e6) / 1e6;
    if (next < 0) {
      throw new Error(
        `Seed history error: ${sku} would fall to ${next} at ${location}. Reduce the movement quantity.`,
      );
    }
    m.set(location, next);
  }

  private total(sku: string): number {
    let sum = 0;
    for (const v of this.leaves(sku).values()) sum += v;
    return Math.round(sum * 1e6) / 1e6;
  }

  run(sku: string, steps: MoveSpec[]): void {
    const product = this.products.get(sku);
    if (!product) throw new Error(`Seed history error: unknown SKU ${sku}`);

    for (const step of steps) {
      const legs: { location: string; delta: number }[] = [];
      let delta = 0;

      if (step.type === 'OPENING') {
        const target = step.to as string;
        delta = step.qty;
        this.apply(sku, target, delta);
        legs.push({ location: target, delta });
      } else if (step.type === 'RECEIPT') {
        delta = step.qty;
        this.apply(sku, step.to as string, delta);
        legs.push({ location: step.to as string, delta });
      } else if (step.type === 'DELIVERY') {
        delta = -step.qty;
        this.apply(sku, step.from as string, delta);
        legs.push({ location: step.from as string, delta });
      } else if (step.type === 'TRANSFER') {
        this.apply(sku, step.from as string, -step.qty);
        this.apply(sku, step.toMove as string, step.qty);
        legs.push({ location: step.from as string, delta: -step.qty });
        legs.push({ location: step.toMove as string, delta: step.qty });
      } else {
        delta = step.qty;
        this.apply(sku, step.to as string, delta);
        legs.push({ location: step.to as string, delta });
      }

      const balanceAfter = this.total(sku);
      this.ledger.push({
        id: `LG-${String(++this.n).padStart(5, '0')}`,
        at: step.at,
        type: step.type,
        ref: step.ref,
        sku,
        name: product.name,
        delta,
        from: step.from ?? (step.type === 'RECEIPT' ? 'Supplier' : '—'),
        to: step.toMove ?? step.to ?? '—',
        legs,
        balanceAfter,
        user: step.user,
        note: step.note,
      });
    }

    // Write the replayed position back onto the product.
    const map: Record<string, number> = {};
    for (const [loc, value] of this.leaves(sku)) {
      if (value > 0) map[loc] = value;
    }
    product.stock = map;
    product.updatedAt = steps[steps.length - 1]?.at.slice(0, 10) ?? product.updatedAt;
  }
}

