/* ------------------------------------------------------------- documents */

function lines(
  items: { sku: string; expected?: number; received: number; bin: string; lot?: string }[],
) {
  return items.map((i, idx) => ({
    id: lineId('RL'),
    sku: i.sku,
    expected: i.expected ?? i.received,
    received: i.received,
    bin: i.bin,
    lot: i.lot ?? `LOT-26${String(idx + 1).padStart(2, '0')}`,
    barcode: '',
  }));
}

function dl(items: { sku: string; qty: number; bin: string; picked?: number; packed?: boolean }[]) {
  return items.map((i) => ({
    id: lineId('DL'),
    sku: i.sku,
    qty: i.qty,
    picked: i.picked ?? i.qty,
    bin: i.bin,
    packed: i.packed ?? true,
  }));
}

function tl(items: { sku: string; qty: number }[]) {
  return items.map((i) => ({ id: lineId('TL'), sku: i.sku, qty: i.qty }));
}

