/* ------------------------------------------------------------------- build */

export function buildSeed(): Database {
  const products: Product[] = PRODUCT_SEEDS.map((p) => ({ ...p, stock: {} }));
  const bySku = new Map(products.map((p) => [p.sku, p]));

  const history = new HistoryBuilder(bySku);
  for (const sku of Object.keys(HISTORY)) history.run(sku, HISTORY[sku]!);
  // Steel rods deliberately have no history: the demo starts at zero.
  bySku.get('STL-ROD-12')!.stock = {};

  const ledger = [...history.ledger].sort((a, b) => a.at.localeCompare(b.at));
  ledger.forEach((entry, idx) => {
    entry.id = `LG-${String(idx + 1).padStart(5, '0')}`;
  });

  // Open documents reserve stock. Reserved is derived from these lines only.
  for (const receipt of RECEIPTS) {
    for (const line of receipt.lines) {
      if (line.barcode === '') line.barcode = bySku.get(line.sku)?.barcode ?? '';
    }
  }

  return {
    version: SEED_VERSION,
    builtAt: `${TODAY}T06:00`,
    settings: {
      company: {
        name: 'StockSense Logistics',
        legalName: 'StockSense Logistics Private Limited',
        gstin: '27AABCS1429B1ZX',
        address: 'Survey 118, Logistics Park Road',
        city: 'Pune',
        country: 'India',
        timezone: 'Asia/Kolkata (IST)',
        currency: '₹',
        fiscalYearStart: '01-04',
      },
      preventNegativeStock: true,
      approvalRequired: true,
      approvalValueThreshold: 2500,
      approvalVariancePct: 2.5,
      defaultUom: 'Units',
      allowPartialDeliveries: false,
      notificationEmail: true,
      notificationInApp: true,
      lowStockDigest: true,
      sessionTimeoutHours: 12,
      theme: 'light',
      density: 'comfortable',
    },
    users: USERS,
    credentials: USERS.map((u) => ({ userId: u.id, ...hashPassword(PASSWORDS[u.id] ?? 'Demo@1234') })),
    categories: CATEGORIES,
    warehouses: WAREHOUSES,
    locations: LOCATIONS,
    products,
    receipts: RECEIPTS,
    deliveries: DELIVERIES,
    transfers: TRANSFERS,
    adjustments: ADJUSTMENTS,
    counts: COUNTS,
    ledger,
    events: [],
    readNotifications: [],
  };
}
